  for(const v of [floor,(floor+ceil)/2,ceil]){const py=165-130*(v-floor)/(ceil-floor);graph.append(svg('line',{x1:60,x2:615,y1:py,y2:py,stroke:'#e7ecf5'}),svg('text',{x:4,y:py+4,fill:'#78859b','font-size':11},number(v)));}
