 function selectionControls(){byId('explorerSelectedCount').textContent=String(chosen.size);byId('explorerPrepare').disabled=!chosen.size||busy;byId('explorerSelectionDownload').disabled=!preview;byId('explorerSave').disabled=!preview||busy;byId('explorerSaveForm').hidden=!packet?.can_save_report;byId('explorerClearSelection').disabled=busy;for(const id of ['explorerReportTitle','explorerReportNote'])byId(id).disabled=busy;for(const c of checks)c.node.disabled=busy||!c.available;
  const box=byId('explorerChosen');box.replaceChildren();for(const [ref,title] of chosen){const row=el('div',undefined,'explorer-chosen'),button=el('button','Quitar','outline');button.type='button';button.disabled=busy;button.onclick=()=>{if(busy)return;chosen.delete(ref);invalidate();renderRows();};row.append(el('span',title),button);box.append(row);}}
