 function clear(){packet=null;checks=[];byId('explorerResults').replaceChildren();byId('explorerCoverage').textContent='';for(const id of ['explorerTotal','explorerNews','explorerSocial','explorerDocuments'])byId(id).textContent='—';byId('explorerPageExport').disabled=true;byId('explorerPrev').disabled=true;byId('explorerNext').disabled=true;byId('explorerSaveForm').hidden=true;}
 function renderRows(){if(!packet)return;checks=[];const box=byId('explorerResults');box.replaceChildren();for(const row of packet.items){const card=el('article',undefined,'explorer-card'),meta=el('div',undefined,'explorer-meta');meta.append(el('span',kinds[row.kind],'rbadge'),el('span',row.source+' · '+bases[row.date_basis]+': '+date(row.at)));const title=el('button',row.title,'explorer-title');title.type='button';title.onclick=()=>open(row.reference);card.append(meta,title,el('p',row.excerpt||'Ficha del archivo guardado.'));
   const label=el('label'),check=el('input'),available=row.kind!=='document'||row.preview_status==='text_verified';checks.push({node:check,available});check.type='checkbox';check.checked=chosen.has(row.reference);check.disabled=busy||!available;check.onchange=()=>{if(busy||!available)return;if(check.checked){if(chosen.size>=8){check.checked=false;byId('explorerSelectionStatus').textContent='Selecciona hasta ocho evidencias.';return;}chosen.set(row.reference,row.title);}else chosen.delete(row.reference);invalidate();};label.append(check,el('span',' Añadir a la selección'));card.append(label);box.append(card);}
  if(!packet.items.length)box.append(el('p','No hay coincidencias en el archivo revisado. Prueba otra palabra o ajusta los filtros.','live-empty'));}
 function render(p){packet=p;for(const [id,rows] of [['explorerActor',p.actors.map(a=>({value:a.id,label:a.name+(a.active?'':' · archivado')}))],['explorerSource',p.sources]]){const node=byId(id),old=node.value;node.replaceChildren();const all=el('option',id==='explorerActor'?'Todos los actores':'Todas las fuentes');all.value=id==='explorerActor'?'0':'';node.append(all);for(const r of rows){const o=el('option',r.label);o.value=r.value;node.append(o);}node.value=old||all.value;}
  byId('explorerTotal').textContent=String(p.matched_in_scan);for(const [id,key] of [['explorerNews','news'],['explorerSocial','social'],['explorerDocuments','document']])byId(id).textContent=String(p.counts[key]);
  byId('explorerCoverage').textContent='Coincidencias dentro del archivo revisado · '+Object.entries(p.coverage.scanned).map(([k,n])=>n+' '+(kinds[k]||k)).join(' · ')+(p.coverage.bounded?' · consulta acotada':'')+(p.coverage.documents_metadata_only?' · '+p.coverage.documents_metadata_only+' archivos revisados por su ficha':'');
  byId('explorerActorScope').textContent=Number(p.filters.actor_id)?'Con actor seleccionado se muestran piezas de redes con vínculo registrado a ese actor.':'';
  byId('explorerPageLabel').textContent=p.items.length?'Resultados '+(p.offset+1)+'–'+(p.offset+p.items.length)+' de '+p.matched_in_scan:'Sin resultados';byId('explorerPrev').disabled=p.offset===0;byId('explorerNext').disabled=!p.has_more;byId('explorerPageExport').disabled=false;renderRows();selectionControls();}
 async function reload(){if(!getProject())return;const stamp=++sequence,pid=getProject();clear();byId('explorerStatus').textContent='Consultando el archivo del proyecto…';
  try{const params={q:byId('explorerQuery').value,kind:byId('explorerKind').value,network:byId('explorerNetwork').value,actor_id:byId('explorerActor').value||0,source:byId('explorerSource').value||'',offset,...dates()};const p=await api(path()+'?'+new URLSearchParams(params));if(stamp!==sequence||pid!==getProject())return;byId('explorerStatus').textContent='';render(p);}
  catch(e){if(stamp===sequence&&pid===getProject())byId('explorerStatus').textContent=e.message;}}
 async function open(reference){const stamp=++detailSequence,pid=getProject();try{const d=await api(path()+'/items/'+encodeURIComponent(reference));if(stamp!==detailSequence||pid!==getProject())return;byId('explorerDetail').hidden=false;byId('explorerDetailTitle').textContent=d.title;byId('explorerDetailMeta').textContent=d.source+' · '+bases[d.date_basis]+': '+date(d.at);byId('explorerDetailText').textContent=d.excerpt||'Este archivo dispone de una ficha; consulta sus documentos desde la biblioteca.';byId('explorerDetailHash').textContent='Referencia '+d.reference+' · huella '+d.content_sha256;
   const links=byId('explorerDetailLinks');links.replaceChildren();if(d.url&&/^https:\/\//i.test(d.url)){const link=el('a','Abrir fuente original ↗');link.href=d.url;link.target='_blank';link.rel='noopener noreferrer';links.append(link);}if(byId('explorerDetail').offsetParent!==null)byId('explorerDetail').scrollIntoView({behavior:'smooth',block:'start'});}
  catch(e){if(stamp===detailSequence&&pid===getProject())byId('explorerStatus').textContent=e.message;}}
 byId('explorerPrepare').onclick=async()=>{if(!chosen.size||busy)return;const pid=getProject(),stamp=++selectionSequence,refs=[...chosen.keys()];busy=true;selectionControls();
  try{const p=await api(path()+'/selection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({references:refs})});if(pid!==getProject()||stamp!==selectionSequence)return;preview=p;selectionSaved=false;const box=byId('explorerSelectionPreview');box.replaceChildren();for(const c of p.citations){const card=el('details',undefined,'explorer-citation');card.append(el('summary',c.title),el('small',c.source),el('p',c.excerpt));box.append(card);}byId('explorerSelectionStatus').textContent=p.citations.length+' evidencias preparadas.';}
  catch(e){if(pid===getProject()&&stamp===selectionSequence)byId('explorerSelectionStatus').textContent=e.message;}finally{busy=false;selectionControls();}};
 byId('explorerSaveForm').onsubmit=async e=>{e.preventDefault();if(!preview||!packet?.can_save_report||busy)return;const pid=getProject();busy=true;selectionControls();
  try{const r=await api(path()+'/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({references:[...chosen.keys()],preview_sha256:preview.preview_sha256,title:byId('explorerReportTitle').value,note:byId('explorerReportNote').value})});if(pid!==getProject())return;dirty=false;selectionSaved=true;byId('explorerSelectionStatus').textContent='Informe guardado en Reportes.';await onSaved(r.id);}
  catch(e){if(pid===getProject())byId('explorerSelectionStatus').textContent=e.message;}finally{busy=false;selectionControls();}};
 byId('explorerForm').onsubmit=e=>{e.preventDefault();offset=0;reload();};for(const id of ['explorerKind','explorerNetwork','explorerActor','explorerSource'])byId(id).onchange=()=>{offset=0;if(['explorerKind','explorerNetwork','explorerActor'].includes(id))byId('explorerSource').value='';reload();};
 byId('explorerPeriod').onchange=()=>{offset=0;byId('explorerDates').hidden=byId('explorerPeriod').value!=='custom';if(byId('explorerPeriod').value!=='custom')reload();else{sequence++;clear();}};
 for(const id of ['explorerFrom','explorerTo'])byId(id).onchange=()=>{sequence++;offset=0;clear();};
 byId('explorerPrev').onclick=()=>{offset=Math.max(0,offset-20);reload();};byId('explorerNext').onclick=()=>{offset+=20;reload();};
 byId('explorerPageExport').onclick=()=>{if(packet)download(packet,'NEXO_Explorador_Pagina.json');};byId('explorerSelectionDownload').onclick=()=>{if(preview)download(preview,'NEXO_Seleccion_Evidencias.json');};
 byId('explorerClearSelection').onclick=()=>{if(busy)return;chosen.clear();invalidate();renderRows();};byId('explorerLibrary').onclick=()=>onLibrary();byId('explorerDetailClose').onclick=()=>{detailSequence++;byId('explorerDetail').hidden=true;};
 for(const id of ['explorerReportTitle','explorerReportNote'])byId(id).oninput=()=>dirty=true;
 function resetProject(){sequence++;detailSequence++;selectionSequence++;chosen.clear();preview=null;offset=0;dirty=false;selectionSaved=false;clear();byId('explorerChosen').replaceChildren();byId('explorerSelectionPreview').replaceChildren();byId('explorerDetail').hidden=true;byId('explorerDetailLinks').replaceChildren();byId('explorerDates').hidden=true;
  for(const id of ['explorerQuery','explorerFrom','explorerTo','explorerReportTitle','explorerReportNote'])byId(id).value='';for(const id of ['explorerActor','explorerSource'])byId(id).replaceChildren();byId('explorerKind').value='all';byId('explorerNetwork').value='all';byId('explorerPeriod').value='all';
  for(const id of ['explorerDetailTitle','explorerDetailMeta','explorerDetailText','explorerDetailHash','explorerStatus','explorerSelectionStatus','explorerPageLabel','explorerActorScope'])byId(id).textContent='';selectionControls();}
